export function directionText(language, key, values = {}) {
  if (key === 'retained' && values.count === 1) return { en: '1 confirmed milestone kept', de: '1 bestätigten Meilenstein behalten', es: '1 hito confirmado conservado', fr: '1 palier confirmé conservé' }[language]
  return messages[language][key].replace(/\{(\w+)\}/g, (_, name) => values[name] ?? '')
}
